this enumeration controls the channel sampling time:
for example if a channel specifies a bone and an origin bone (used to generate the reference system of the features associated to the bone),
bone and origin bone will be evaluated at potentially different times:

UENUM(BlueprintType)
enum class ERBFSolverType : uint8
{
       Additive,
       Interpolative
};

UENUM(BlueprintType)
enum class ERBFFunctionType : uint8
{
       Gaussian,
       Exponential,
       Linear,
       Cubic,
       Quintic,
};

UENUM(BlueprintType)
enum class ERBFDistanceMethod : uint8
{
       Euclidean,
       Quaternion,
       SwingAngle,
       TwistAngle,
};

UENUM(BlueprintType)
enum class ERBFNormalizeMethod : uint8
{
       OnlyNormalizeAboveOne,
       AlwaysNormalize
};

